/* ==========================================================================
   Mi RCR — pies.js
   Pie de página institucional por área (franja de logos de aliados),
   provisto como PNG y embebido en data URI para que el PDF no dependa
   de la red. Recortado de los diseños originales.
   "ar" = ancho/alto, para escalar la franja sin deformar.
   ========================================================================== */

window.PIES = {
  /* Pie ReCircula — 896x73 */
  recircula: { ar: 12.274, src: "data:image/png;base64," },
  /* Pie Juntos Por La Vida — 907x66 */
  juntos_vida: { ar: 13.7424, src: "data:image/png;base64," }
};

/* Devuelve la franja de pie escalada al ancho dado (px). */
window.pieImg = function (areaKey, ancho) {
  var P = window.PIES[areaKey];
  if (!P) return '';
  return '<img src="' + P.src + '" alt="" style="width:' + ancho + 'px;height:auto;display:block">';
};
